#include<bits/stdc++.h>
using namespace std;
int main(){
    int N;
    scanf("%d",&N);
    vector<int>par(N+1,0);
    vector<vector<int>>ch(N+1);
    for(int i=2;i<=N;i++){
        scanf("%d",&par[i]);
        ch[par[i]].push_back(i);
    }
    vector<int>leaves;
    {
        stack<int>st;
        st.push(1);
        while(!st.empty()){
            int v=st.top();st.pop();
            if(ch[v].empty())leaves.push_back(v);
            for(int i=(int)ch[v].size()-1;i>=0;i--)st.push(ch[v][i]);
        }
    }
    int numL=(int)leaves.size();
    vector<set<int>>adj(N+1);
    for(int i=2;i<=N;i++){adj[i].insert(par[i]);adj[par[i]].insert(i);}
    for(int i=0;i<numL;i++){
        int u=leaves[i],v=leaves[(i+1)%numL];
        if(u!=v){adj[u].insert(v);adj[v].insert(u);}
    }
    vector<bool>elim(N+1,false);
    vector<vector<int>>bags;
    vector<int>elimOrd;
    vector<int>elimStep(N+1,-1);
    priority_queue<pair<int,int>,vector<pair<int,int>>,greater<>>pq;
    for(int v=1;v<=N;v++)pq.push({(int)adj[v].size(),v});
    for(int step=0;step<N;step++){
        while(elim[pq.top().second])pq.pop();
        // re-check degree
        int bv=pq.top().second;pq.pop();
        // Actually just do linear scan for correctness
        int bd=N+2;bv=-1;
        for(int v=1;v<=N;v++)if(!elim[v]&&(int)adj[v].size()<bd){bd=(int)adj[v].size();bv=v;}
        vector<int>bag;
        bag.push_back(bv);
        vector<int>nbrs(adj[bv].begin(),adj[bv].end());
        for(int x:nbrs)bag.push_back(x);
        bags.push_back(bag);
        elimOrd.push_back(bv);
        elimStep[bv]=step;
        for(int i=0;i<(int)nbrs.size();i++)
            for(int j=i+1;j<(int)nbrs.size();j++){
                adj[nbrs[i]].insert(nbrs[j]);
                adj[nbrs[j]].insert(nbrs[i]);
            }
        for(int x:nbrs)adj[x].erase(bv);
        adj[bv].clear();
        elim[bv]=true;
    }
    int width=0;
    for(auto&b:bags)width=max(width,(int)b.size());
    vector<int>bagPar(N,-1);
    for(int i=0;i<N;i++){
        int minS=N,best=-1;
        for(int v:bags[i])if(v!=elimOrd[i]&&elimStep[v]>i&&elimStep[v]<minS){minS=elimStep[v];best=elimStep[v];}
        if(best!=-1)bagPar[i]=best;
    }
    printf("s td %d %d %d\n",N,width,N);
    for(int i=0;i<N;i++){
        printf("b %d",i+1);
        for(int v:bags[i])printf(" %d",v);
        printf("\n");
    }
    for(int i=0;i<N;i++)if(bagPar[i]!=-1)printf("%d %d\n",i+1,bagPar[i]+1);
    return 0;
}
